1	package com.example.starter.blind.web;
2	
3	import com.example.starter.blind.Actor;
4	import com.example.starter.blind.ActorContext;
5	import com.example.starter.blind.ApiException;
6	import com.example.starter.blind.RequestTokens;
7	import com.example.starter.blind.dto.AllocationView;
8	import com.example.starter.blind.dto.CreateExperimentRequest;
9	import com.example.starter.blind.dto.ExperimentView;
10	import com.example.starter.blind.dto.UnblindApplyRequest;
11	import com.example.starter.blind.dto.UnblindRequestView;
12	import com.example.starter.blind.dto.UnblindResultView;
13	import com.example.starter.blind.service.ExperimentService;
14	import com.example.starter.blind.service.IdempotencyService;
15	import com.example.starter.blind.service.UnblindService;
16	import jakarta.validation.Valid;
17	import org.springframework.http.HttpStatus;
18	import org.springframework.http.ResponseEntity;
19	import org.springframework.web.bind.annotation.GetMapping;
20	import org.springframework.web.bind.annotation.PathVariable;
21	import org.springframework.web.bind.annotation.PostMapping;
22	import org.springframework.web.bind.annotation.RequestBody;
23	import org.springframework.web.bind.annotation.RequestHeader;
24	import org.springframework.web.bind.annotation.RequestMapping;
25	import org.springframework.web.bind.annotation.RestController;
26	
27	import java.util.Map;
28	
29	/**
30	 * 实验盲法分配与受控揭盲接口。
31	 * 所有写操作必须携带 X-Request-Id；权限校验先于幂等回放。
32	 */
33	@RestController
34	@RequestMapping("/api")
35	public class BlindExperimentController {
36	
37	    static final String OP_EXPERIMENT_CREATE = "experiment.create";
38	    static final String OP_EXPERIMENT_CLOSE = "experiment.close";
39	    static final String OP_ALLOCATION_CREATE = "allocation.create";
40	    static final String OP_ALLOCATION_WITHDRAW = "allocation.withdraw";
41	    static final String OP_UNBLIND_APPLY = "unblind.apply";
42	    static final String OP_UNBLIND_APPROVE = "unblind.approve";
43	
44	    private final ExperimentService experimentService;
45	    private final UnblindService unblindService;
46	    private final IdempotencyService idempotencyService;
47	    private final ActorContext actorContext;
48	
49	    public BlindExperimentController(ExperimentService experimentService,
50	                                     UnblindService unblindService,
51	                                     IdempotencyService idempotencyService,
52	                                     ActorContext actorContext) {
53	        this.experimentService = experimentService;
54	        this.unblindService = unblindService;
55	        this.idempotencyService = idempotencyService;
56	        this.actorContext = actorContext;
57	    }
58	
59	    // ---------------- 实验 ----------------
60	
61	    /** 创建实验（仅 COORDINATOR）；区组数量 2~8，创建后不可改。 */
62	    @PostMapping("/experiments/{experimentId}")
63	    public ResponseEntity<String> createExperiment(
64	            @PathVariable String experimentId,
65	            @Valid @RequestBody CreateExperimentRequest request,
66	            @RequestHeader(IdempotencyService.HEADER_REQUEST_ID) String requestId) {
67	        Actor actor = requireCoordinator();
68	        String expId = RequestTokens.requireId("experimentId", experimentId);
69	        String reqId = RequestTokens.requireRequestId(requestId);
70	        String fingerprint = idempotencyService.fingerprint(OP_EXPERIMENT_CREATE,
