1	package com.example.starter.blind.service;
2	
3	import com.example.starter.blind.ApiException;
4	import com.example.starter.blind.Clock;
5	import com.example.starter.blind.dto.AllocationView;
6	import com.example.starter.blind.dto.ExperimentView;
7	import com.example.starter.blind.repo.AllocationRepository;
8	import com.example.starter.blind.repo.AllocationRepository.AllocationRow;
9	import com.example.starter.blind.repo.AllocationRepository.VacantSeat;
10	import com.example.starter.blind.repo.ExperimentRepository;
11	import com.example.starter.blind.repo.ExperimentRepository.ExperimentRow;
12	import com.example.starter.blind.repo.ExperimentRepository.SeatRow;
13	import org.springframework.dao.DuplicateKeyException;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.annotation.Transactional;
16	
17	import java.util.ArrayList;
18	import java.util.List;
19	
20	/**
21	 * 实验与分配核心业务：
22	 * 创建实验时固定区组与每区组两 A 两 B 的席位内容；分配按区组、席位顺序领取第一个空位；
23	 * 退组保留席位不重排；关闭后拒绝新增分配。普通视图不含席位号与处理代码。
24	 */
25	@Service
26	public class ExperimentService {
27	
28	    static final int SEATS_PER_BLOCK = 4;
29	
30	    private final ExperimentRepository experimentRepository;
31	    private final AllocationRepository allocationRepository;
32	    private final BlindCodeGenerator blindCodeGenerator;
33	    private final Clock clock;
34	
35	    public ExperimentService(ExperimentRepository experimentRepository,
36	                             AllocationRepository allocationRepository,
37	                             BlindCodeGenerator blindCodeGenerator,
38	                             Clock clock) {
39	        this.experimentRepository = experimentRepository;
40	        this.allocationRepository = allocationRepository;
41	        this.blindCodeGenerator = blindCodeGenerator;
42	        this.clock = clock;
43	    }
44	
45	    /**
46	     * 创建实验并固定席位：每区组按席位顺序两个 A、两个 B。
47	     * 不记录任何处理映射到日志。
48	     */
49	    @Transactional
50	    public ExperimentView createExperiment(String experimentId, int blockCount) {
51	        if (experimentId == null || experimentId.isBlank()) {
52	            throw ApiException.badRequest("experimentId 不能为空");
53	        }
54	        if (experimentRepository.findById(experimentId) != null) {
55	            throw ApiException.conflict("实验已存在: " + experimentId);
56	        }
57	        long now = clock.nowMillis();
58	        experimentRepository.insertExperiment(
59	                new ExperimentRow(experimentId, blockCount, "OPEN", now));
60	        List<SeatRow> seats = new ArrayList<>(blockCount * SEATS_PER_BLOCK);
61	        for (int blockNo = 1; blockNo <= blockCount; blockNo++) {
62	            for (int seatNo = 1; seatNo <= SEATS_PER_BLOCK; seatNo++) {
63	                // 按提交顺序：每区组前两席 A，后两席 B；内容创建后不可改。
64	                String treatment = seatNo <= 2 ? "A" : "B";
65	                seats.add(new SeatRow(experimentId, blockNo, seatNo, treatment));
66	            }
67	        }
68	        seats.forEach(experimentRepository::insertSeat);
69	        return new ExperimentView(experimentId, blockCount, SEATS_PER_BLOCK,
70	                blockCount * SEATS_PER_BLOCK, "OPEN", now);
71	    }
72	
73	    public ExperimentView getExperiment(String experimentId) {
74	        ExperimentRow row = mustFindExperiment(experimentId);
75	        return new ExperimentView(row.id(), row.blockCount(), SEATS_PER_BLOCK,
76	                row.blockCount() * SEATS_PER_BLOCK, row.status(), row.createdAt());
77	    }
78	
79	    /**
80	     * 原子领取第一个空位；实验行级锁串行化同实验并发分配。
81	     */
82	    @Transactional
83	    public AllocationView register(String experimentId, String participantId, String actorId) {
84	        if (participantId == null || participantId.isBlank()) {
85	            throw ApiException.badRequest("participantId 不能为空");
86	        }
87	        ExperimentRow experiment = experimentRepository.lockById(experimentId);
88	        if (experiment == null) {
89	            throw ApiException.notFound("实验不存在: " + experimentId);
90	        }
91	        if ("CLOSED".equals(experiment.status())) {
92	            throw ApiException.conflict("实验已关闭，拒绝新增分配");
93	        }
94	        AllocationRow existing =
95	                allocationRepository.findByExperimentAndParticipant(experimentId, participantId);
96	        if (existing != null) {
97	            // 同实验同参与者只占一席；已退组也不重新占席。
98	            throw ApiException.conflict("参与者已在该实验登记，仅可占一席");
99	        }
100	        VacantSeat vacant = allocationRepository.takeFirstVacantSeat(experimentId);
101	        if (vacant == null) {
102	            throw ApiException.full("实验席位已满");
103	        }
104	        long now = clock.nowMillis();
105	        AllocationRow inserted = insertWithUniqueBlindCode(experimentId, participantId, actorId,
106	                vacant, now);
107	        return toView(inserted);
108	    }
109	
110	    private AllocationRow insertWithUniqueBlindCode(String experimentId, String participantId,
111	                                                    String actorId, VacantSeat vacant, long now) {
112	        // 盲码随机冲突概率极低，仍由唯一索引兜底并重试。
113	        for (int attempt = 0; attempt < 5; attempt++) {
114	            String blindCode = blindCodeGenerator.nextCode();
115	            AllocationRow row = new AllocationRow(0L, experimentId, participantId,
116	                    vacant.blockNo(), vacant.seatNo(), blindCode, "ASSIGNED",
117	                    actorId, now, null);
118	            try {
119	                allocationRepository.insert(row);
120	                return allocationRepository.findByExperimentAndParticipant(experimentId, participantId);
121	            } catch (DuplicateKeyException e) {
122	                if (allocationRepository.isDuplicateBlindCode(e)) {
123	                    continue;
124	                }
125	                if (allocationRepository.isDuplicateSeat(e)
126	                        || allocationRepository.isDuplicateParticipant(e)) {
