    @Test
    void sameRequestIdConcurrentAnalysis_exactlyOneRecordAllReplaySame() throws Exception {
        createExperiment("ACC-3", "acc3-create");
        for (int i = 1; i <= 4; i++) {
            register("ACC-3", "P" + i, "acc3-alloc-" + i);
